data.query:
query ($workcenterId: String!) {
  productionSetupOutput(where: {workcenterId: {_eq: $workcenterId}}) {
    total
    edges {
      node {
        id
        counterInput
        cycleTime
        workOrderDistribution {
          productionOperators
        }
        distributionQuantity
        workOrderProcessId
        workOrderId
        productId
        productStrategyProcessId
        idealRate
        producedQuantity
        remainingBalance
        scrappedQuantity
        setupRate
        defaultProductionQuantity
        standardRate
        unitPerCycle
        startAt
        customData
        workcenterId
        productionSetupId
      }
    }
  }
  productionSetup(where: {workcenterId: {_eq: $workcenterId}}) {
    edges {
      node {
        id
        workcenterId
        productionRunId
        productionRun {
          startAt
        }
        operators {
          total
        }
        productionSetupQualitySubjectLists(where: {qualitySubjectList: {_and: {usable:{_eq: true}, interval:{qualityIntervalTypeId: { _in: ["IntraProcess-Hours", "IntraProcess-Minutes", "PreProcess", "PostProcess"]}}}}} ){
          edges{
            node{
              workOrderId
              workOrderProcessId
              qualitySubjectListId
              qualitySubjectList{
                lotControlId
                processId
                productId
                productProcessId
                workcenterId
                specificationGroup{
                  id
                  name
                }
                usable
                id
                interval{
                  processOffset
                  repeat
                  qualityIntervalTypeId
                }
              }
            }
          }
        }
        modeId
        eventId
        productionAssets {
          edges {
            node {
              assetId
              assetGroup{
                assets{
                  edges{
                    node{
                      assetId :id
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  workcenter(where: {id: {_eq: $workcenterId}}) {
    edges {
      node {
        shiftGroup {
          id
          shifts {
            edges {
              node {
                shift {
                  id
                  name
                  creditAtStart
                  monday
                  tuesday
                  wednesday
                  thursday
                  friday
                  saturday
                  sunday
                  startAt
                  endAt
                }
              }
            }
          }
        }
      }
    }
  }
  setting(where: {id: {_eq: "TimeZone"}}) {
    edges {
      node {
        defaultValue
      }
    }
  }
}

data.transform:
(
  $defaultToZero := function($value){ $coalesce([$value, 0]) };
  $outputs := productionSetupOutput.edges.node;
  $now := $moment().format();
  $runId := $cuid();
  $workcenterHistoryId := $cuid();

  $shift := $executeTransform(
    "getShift",
    {
      "date": $now,
      "shiftGroupId": workcenter.edges.node.shiftGroup.id,
      "timezone": setting.edges.node.defaultValue
    }
  );

  $assets := [
     productionSetup.edges.node.productionAssets.edges.node[$isNil(assetGroup)],
     productionSetup.edges.node.productionAssets.edges.node.assetGroup.assets.edges.node
  ];

  {
    "runPayload":{
      "create": {
        "id": $runId,
        "idealAggregate": $sum([$outputs.idealRate.($defaultToZero($))]),
        "standardAggregate": $sum([$outputs.standardRate.($defaultToZero($))]),
        "averageCycleTime": 0,
        "changeoverAggregate": $sum([$outputs.setupRate.($defaultToZero($))]),
        "runCrewSize": productionSetup.edges.node.operators.total,
        "workcenterId":productionSetup.edges.node.workcenterId,
        "startAt": $now,
        "productionSetupId": productionSetup.edges.node.id,
        "totalRequired": $sum([$outputs.distributionQuantity.($defaultToZero($))]),
        "excludedProduction": 0,
        "excludedScrap":0,
        "crewAggregate": $sum([productionSetup.edges.node.operators.total.($defaultToZero($))])
      }
    },
    "setupPayload":{
      "where":{ "id": productionSetup.edges.node.id },
      "update":{ "productionRunId": $runId}

    },
    "workcenterHistoryPayload":{
      "create": 
        { 
          "id": $workcenterHistoryId,
          "transactionTypeId": "Production Setup Add",
          "productionRunId": $runId,
          "workcenterId": productionSetup.edges.node.workcenterId,
          "shiftId": $shift.id,
          "occurAt": $now,

          "creditedAt": $shift.creditAt,
          "modeId":productionSetup.edges.node.modeId,
          "eventId": productionSetup.edges.node.eventId,
          "message": "Production Run: " & $runId & " Started",
          "customData": $dist.{
            "groupId": $g.id,
            "distId": id,
